static bool interior(double x, double y) {
    const double y2 = y * y;
    const double xm = x - 0.25;
    const double q = xm * xm + y2;
    const double xp = x + 1.0;
    return q * (q + xm) <= 0.25 * y2 ||
           xp * xp + y2 <= 0.0625;
}

static void scalar_row(const double* xs, double ci, int n,
                       unsigned char* output) {
    for (int x = 0; x < n;) {
        unsigned char byte = 0;
        for (int bit = 0; bit < 8 && x < n; ++bit, ++x) {
            const double cr = xs[x];
            bool bounded = interior(cr, ci);
            if (!bounded) {
                double zr = 0.0, zi = 0.0;
                bounded = true;
                for (int iteration = 0; iteration < 50; ++iteration) {
                    const double next_r = zr * zr - zi * zi + cr;
                    zi = (zr + zr) * zi + ci;
                    zr = next_r;
                    if (zr * zr + zi * zi > 4.0) {
                        bounded = false;
                        break;
                    }
                }
            }
            if (bounded)
                byte |= static_cast<unsigned char>(0x80u >> bit);
        }
        *output++ = byte;
    }
}

