static inline __m256d interior_mask(__m256d cr, __m256d ci2) {
    const __m256d quarter = _mm256_set1_pd(0.25);
    const __m256d xm = _mm256_sub_pd(cr, quarter);
    const __m256d q = _mm256_add_pd(_mm256_mul_pd(xm, xm), ci2);
    const __m256d cardioid = _mm256_cmp_pd(
        _mm256_mul_pd(q, _mm256_add_pd(q, xm)),
        _mm256_mul_pd(quarter, ci2), _CMP_LE_OQ);

    const __m256d xp = _mm256_add_pd(cr, _mm256_set1_pd(1.0));
    const __m256d bulb = _mm256_cmp_pd(
        _mm256_add_pd(_mm256_mul_pd(xp, xp), ci2),
        _mm256_set1_pd(0.0625), _CMP_LE_OQ);
    return _mm256_or_pd(cardioid, bulb);
}

