static void avx2_row(const double* xs, double imaginary, int n,
                     unsigned char* output) {
    const __m256d zero = _mm256_setzero_pd();
    const __m256d four = _mm256_set1_pd(4.0);
    const __m256d ci = _mm256_set1_pd(imaginary);
    const __m256d ci2 = _mm256_mul_pd(ci, ci);
    const std::size_t bytes = (static_cast<std::size_t>(n) + 7) / 8;

    for (std::size_t b = 0; b < bytes; ++b) {
        const __m256d cr0 = _mm256_loadu_pd(xs + b * 8);
        const __m256d cr1 = _mm256_loadu_pd(xs + b * 8 + 4);
        const __m256d inside0 = interior_mask(cr0, ci2);
        const __m256d inside1 = interior_mask(cr1, ci2);

        const unsigned inside =
            static_cast<unsigned>(_mm256_movemask_pd(inside0)) |
            (static_cast<unsigned>(_mm256_movemask_pd(inside1)) << 4);

        unsigned escaped = 0;
        if (inside != 255u) {
            __m256d zr0 = zero, zi0 = zero;
            __m256d zr1 = zero, zi1 = zero;
            __m256d zr20 = zero, zi20 = zero;
            __m256d zr21 = zero, zi21 = zero;
            __m256d escaped0 = zero, escaped1 = zero;

            for (int iteration = 0; iteration < 50; ++iteration) {
                zi0 = _mm256_add_pd(
                    _mm256_mul_pd(_mm256_add_pd(zr0, zr0), zi0), ci);
                zi1 = _mm256_add_pd(
                    _mm256_mul_pd(_mm256_add_pd(zr1, zr1), zi1), ci);
                zr0 = _mm256_add_pd(_mm256_sub_pd(zr20, zi20), cr0);
                zr1 = _mm256_add_pd(_mm256_sub_pd(zr21, zi21), cr1);

                zr20 = _mm256_mul_pd(zr0, zr0);
                zi20 = _mm256_mul_pd(zi0, zi0);
                zr21 = _mm256_mul_pd(zr1, zr1);
                zi21 = _mm256_mul_pd(zi1, zi1);

                escaped0 = _mm256_or_pd(
                    escaped0,
                    _mm256_cmp_pd(_mm256_add_pd(zr20, zi20),
                                  four, _CMP_GT_OQ));
                escaped1 = _mm256_or_pd(
                    escaped1,
                    _mm256_cmp_pd(_mm256_add_pd(zr21, zi21),
                                  four, _CMP_GT_OQ));

                escaped =
                    static_cast<unsigned>(_mm256_movemask_pd(escaped0)) |
                    (static_cast<unsigned>(_mm256_movemask_pd(escaped1)) << 4);
                if ((escaped | inside) == 255u)
                    break;
            }
        }

        unsigned bits = ((~escaped) | inside) & 255u;
        bits = ((bits & 0x55u) << 1) | ((bits >> 1) & 0x55u);
        bits = ((bits & 0x33u) << 2) | ((bits >> 2) & 0x33u);
        bits = ((bits & 0x0fu) << 4) | ((bits >> 4) & 0x0fu);
        output[b] = static_cast<unsigned char>(bits);
    }

    if (n & 7)
        output[bytes - 1] &= static_cast<unsigned char>(0xffu << (8 - (n & 7)));
}
#endif

int main(int argc, char** argv) {
    if (argc < 2)
        return 1;

    errno = 0;
    char* end = nullptr;
    const long parsed = std::strtol(argv[1], &end, 10);
    if (errno || end == argv[1] || *end != '\0' ||
        parsed <= 0 || parsed > INT_MAX)
        return 1;

    const int n = static_cast<int>(parsed);
    const std::size_t row_bytes = (static_cast<std::size_t>(n) + 7) / 8;
    if (row_bytes > std::numeric_limits<std::size_t>::max() /
                        static_cast<std::size_t>(n))
        return 1;

    std::vector<unsigned char> image(row_bytes * static_cast<std::size_t>(n));
    std::vector<double> xs(row_bytes * 8);
    const double scale = 2.0 / static_cast<double>(n);
    for (std::size_t x = 0; x < xs.size(); ++x)
        xs[x] = scale * static_cast<double>(x) - 1.5;

    using RowFunction = void (*)(const double*, double, int, unsigned char*);
    RowFunction render_row = scalar_row;
#if HAVE_AVX2_KERNEL
    __builtin_cpu_init();
    if (__builtin_cpu_supports("avx2"))
        render_row = avx2_row;
#endif

    unsigned workers = std::thread::hardware_concurrency();
    if (!workers)
        workers = 1;
    workers = std::min(workers, 64u);
    workers = std::min(workers, static_cast<unsigned>(n));

    std::atomic<std::size_t> next_row{0};
    auto render = [&]() {
        constexpr std::size_t block_size = 4;
        for (;;) {
            const std::size_t first =
                next_row.fetch_add(block_size, std::memory_order_relaxed);
            if (first >= static_cast<std::size_t>(n))
                break;
            const std::size_t last =
                std::min(first + block_size, static_cast<std::size_t>(n));
            for (std::size_t y = first; y < last; ++y) {
                render_row(xs.data(), scale * static_cast<double>(y) - 1.0,
                           n, image.data() + y * row_bytes);
            }
        }
    };

    std::vector<std::thread> threads;
    threads.reserve(workers - 1);
    for (unsigned i = 1; i < workers; ++i)
        threads.emplace_back(render);
    render();
    for (auto& thread : threads)
        thread.join();

    std::printf("P4\n%d %d\n", n, n);
    return std::fwrite(image.data(), 1, image.size(), stdout) == image.size()
               ? 0 : 1;
}

